"""The rosetta_build corpus case must be a genuine rosetta-core artifact: generated by
`rosetta sync`, consistent with its lock file, and free of the false claim that the
lock tracks the canonical fields store."""
import hashlib
import json
import re
from pathlib import Path

import yaml

CASE = Path(__file__).resolve().parent.parent / "corpus" / "rosetta_build"
SOURCE = CASE / "source"
CORE_AUTO_START = "<!-- ROSETTA:AUTO-GENERATED — do not edit below this marker, edits will be overwritten by `rosetta sync` -->"
CORE_NOTES_START = "<!-- ROSETTA:NOTES — hand-written, sync never touches this region -->"


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _human() -> str:
    return (CASE / "human.md").read_text(encoding="utf-8")


def _machine_fields() -> dict:
    fields = {}
    for line in (CASE / "machine.cpn").read_text(encoding="utf-8").splitlines():
        key, _, value = line.partition("=")
        if key and key != "SCHEMA_VER":
            fields[key] = value
    return fields


def test_views_match_the_lock_file():
    lock = json.loads((SOURCE / "rosetta_build.rosetta.lock").read_text(encoding="utf-8"))
    assert _sha(_human()) == lock["human_hash"]
    assert _sha((CASE / "machine.cpn").read_text(encoding="utf-8")) == lock["machine_hash"]


def test_human_view_uses_core_generated_markers():
    assert CORE_AUTO_START in _human()
    assert CORE_NOTES_START in _human()


def test_both_views_and_the_fields_store_agree():
    match = re.search(r"<!-- ROSETTA:FIELDS (\{.*?\}) -->", _human())
    human_fields = {k: str(v) for k, v in json.loads(match.group(1)).items()}
    store = json.loads((SOURCE / "rosetta_build.fields.json").read_text(encoding="utf-8"))["fields"]
    assert human_fields == _machine_fields() == {k: str(v) for k, v in store.items()}


def test_notes_do_not_claim_the_lock_tracks_the_fields_store():
    assert "Canonical fields, the packet, and the human view are all" not in _human()
    assert "not detected" in _human()


def test_provenance_records_the_generating_core_commit():
    provenance = yaml.safe_load((SOURCE / "PROVENANCE.yaml").read_text(encoding="utf-8"))
    assert re.fullmatch(r"[0-9a-f]{40}", provenance["core_commit"])
    assert provenance["generated_by"].startswith("rosetta sync")


def test_every_answer_key_value_appears_in_the_machine_view():
    answers = yaml.safe_load((CASE / "answer_key.yaml").read_text(encoding="utf-8"))
    values = set(_machine_fields().values())
    assert all(item["answer"] in values for item in answers)
